query.base:
TS metrics-gcp.bigquery.otel-*
// Non-interactive jobs in PENDING state: batch-priority queries plus load/copy/extract jobs.
// Batch work is designed to wait for idle capacity, so this rule only fires when the queue almost never drains.
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
  AND attributes.state == "pending"
  // Exclude interactive queries. Only query jobs carry priority "interactive", so a series with that priority
  // and no job_type label is treated as a query. COALESCE keeps every other unlabelled series
  // (NOT of a null comparison would silently drop it).
  AND NOT (COALESCE(attributes.job_type, "query") == "query" AND COALESCE(attributes.priority, "") == "interactive")
// Stage 1: one value per minute per logical series (MAX collapses fragmented TSIDs of the same series)
| STATS pending = MAX(MAX_OVER_TIME(`metrics.bigquery.googleapis.com/job/num_in_flight`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id, resource.attributes.location, attributes.job_type, attributes.priority
// Series without a job_type label are grouped (and alerted) explicitly as "unknown"
| EVAL attributes.job_type = COALESCE(attributes.job_type, "unknown")
// Stage 2: pending jobs per job type per minute (summed across priorities)
| STATS pending = SUM(pending)
    BY @timestamp, resource.attributes.project_id, resource.attributes.location, attributes.job_type
| WHERE pending IS NOT NULL
// Customise: minimum pending jobs for a minute to count as backlogged
| STATS backlogged_minutes = COUNT(*) WHERE pending >= 1,
        drained_minutes = COUNT(*) WHERE pending < 1,
        min_pending_jobs = MIN(pending),
        peak_pending_jobs = MAX(pending),
        latest_pending_jobs = LAST(pending, @timestamp)
    BY resource.attributes.project_id, resource.attributes.location, attributes.job_type
// Unrounded, so the threshold is exact (94.95% must not count as 95%); rounded only for display below
| EVAL backlogged_pct = backlogged_minutes * 100.0 / (backlogged_minutes + drained_minutes)

breach.segment:
// Customise: alert when jobs were pending in >= 90 one-minute samples and in >= 95% of the reported
// minutes. A ratio, not "never drained": one sample catching an empty queue must not hide a backlog.
// job/num_in_flight publishes up to ~12 minutes late, so a 120-minute window holds ~108 visible minutes.
WHERE backlogged_minutes >= 90 AND backlogged_pct >= 95.0
| EVAL backlogged_pct = ROUND(backlogged_pct, 1)
| SORT backlogged_minutes DESC, peak_pending_jobs DESC
| LIMIT 50
